"""Offline Canvas reviewer with actual approved GIF exposures and bound click tracks."""
import base64,json,hashlib,importlib.util
from pathlib import Path
from PIL import Image
P=Path(__file__).resolve().parent;ROOT=P.parents[2];B=P/'size-locked-review'
d=json.loads((B/'review-data.json').read_text())
d['before']=json.loads((P/'attempt6-review/review-data.json').read_text());d['size_qa']=json.loads((P/'size-locked-qa.json').read_text());d['before_size_qa']=json.loads((P/'before-size-qa.json').read_text())
d['parts']=json.loads((P/'part-proportion-qa.json').read_text())
sp=importlib.util.spec_from_file_location('size',ROOT/'skills/modular-eight-direction-sprites/scripts/character-size-audit.py');size=importlib.util.module_from_spec(sp);sp.loader.exec_module(size)
re=size.extent(ROOT/json.loads((P/'character-size-profile.json').read_text())['reference']['path']);se=size.extent(P/'source/rear/00.png');s=(re['height']-1)/(se['height']-1);tx=192-s*192;ty=re['bbox_xyxy'][1]-s*se['bbox_xyxy'][1];S=P/'viewer-source';S.mkdir(exist_ok=True);bindings=[]
for i in range(8):
    path=S/f'{i:02}.png';Image.open(P/f'source/rear/{i:02}.png').convert('RGBA').transform((384,512),Image.Transform.AFFINE,(1/s,0,-tx/s,0,1/s,-ty/s),Image.Resampling.BICUBIC).save(path);bindings.append(dict(path=str(path.relative_to(ROOT)),sha256=hashlib.sha256(path.read_bytes()).hexdigest()))
d['source_display']=dict(matrix=[s,0,0,s,tx,ty],frames=bindings,scope='Source-only viewer normalization from neutral0 once to approved399px height/480floor. Physical world/camera/projection records stay original; overlays use this same declared display transform.')
(P/'source-display-normalization.json').write_text(json.dumps(d['source_display'],indent=2)+'\n')
paths={r['path'] for r in d['candidate_frames']+d['before']['candidate_frames']+bindings}|{f['decoded_path'] for r in d['reference'] for f in r['frames']}
images={p:'data:image/png;base64,'+base64.b64encode((ROOT/p).read_bytes()).decode() for p in paths}
html='''<!doctype html><meta charset="utf-8"><title>Approved GIF / pickup review</title>
<style>body{background:#17232e;color:#eef4fa;font:16px system-ui;margin:22px}h1{font-size:24px}.row{display:flex;gap:14px;flex-wrap:wrap}figure{margin:0}canvas{width:320px;height:427px;background:#344351;border:1px solid #536271}figcaption{margin:8px 0}button,select,input{font:inherit;margin:6px 5px 6px 0}p{max-width:1050px;line-height:1.55}.fail{color:#ffbd93}pre{font-size:12px;max-height:150px;overflow:auto}label{white-space:nowrap}</style>
<h1>เทียบกับ GIF ที่แอพพรูพ — ทีละเฟรมบนเวลาเดียวกัน</h1>
<p class="fail" id="verdict"></p>
<div class="row"><figure><figcaption>GIF v39 ที่คุณแอพพรูพแล้ว (เฟรมที่ถอดจริง)</figcaption><canvas id="approved" width="384" height="512"></canvas></figure><figure><figcaption>ภาพใหม่ v41 / เก็บไว้ตรวจ ยังไม่ผ่าน</figcaption><canvas id="candidate" width="384" height="512"></canvas></figure><figure><figcaption>กระดูกต้นแบบมุมหลัง / source เท่านั้น</figcaption><canvas id="source" width="384" height="512"></canvas></figure></div>
<p><button id="play">เล่นหนึ่งครั้ง</button><select id="profile"><option value="matched">ล็อกสเกลทั้งชุดจาก GIF เก่า</option><option value="before">ก่อนแก้ขนาด / ไม่ผ่าน</option></select><select id="clock"><option value="source">เวลาตาม approved source GIF</option><option value="game">เวลาตาม approved game GIF</option></select><input id="frame" type="range" min="0" max="7" value="0"><label><input id="grid" type="checkbox">กริด20px</label><label><input id="bones" type="checkbox">กระดูกเฉพาะช่องต้นแบบ</label><label><input id="surfaces" type="checkbox">ขอบรองเท้าที่วัดจริง</label></p><p id="status"></p>
<p>กดซ้าย/ขวาเพื่อเลื่อนเฟรม คลิกในภาพใหม่เพื่อจดจุดที่มองเห็น ชื่อซ้าย/ขวาเป็นการจดด้วยคน ไม่ใช่ผลตรวจอัตโนมัติ หากถูกบังให้เลือก “มองไม่เห็น” ข้อมูลผูกกับ SHA ของภาพแต่ละเฟรม</p>
<p><select id="landmark"><option>visible_neck_receiver</option><option>right_picking_glove</option><option>left_free_glove</option><option>near_boot_surface</option><option>far_boot_surface</option></select><select id="visibility"><option value="visible">มองเห็น</option><option value="unknown">มองไม่เห็น / ไม่แน่ใจ</option></select><button id="unknown">จดว่าไม่ทราบ</button><button id="download">ดาวน์โหลดจุดที่จด</button></p><pre id="notes"></pre>
<p><label><input id="partOverlay" type="checkbox">จุดวัดขนาดส่วนที่เห็นจริง</label></p><p id="partStatus"></p><pre id="partTable"></pre>
<script>
const DATA=__DATA__,URLS=__IMAGES__,images={},ctxs=Object.fromEntries(['approved','candidate','source'].map(k=>[k,document.getElementById(k).getContext('2d')]));let ready=false,index=0,running=false,clock='source',profile='matched',start=0;const observations={matched:Array.from({length:8},()=>({})),before:Array.from({length:8},()=>({}))};const active=()=>profile==='matched'?DATA:DATA.before,obs=()=>observations[profile];
Promise.all(Object.entries(URLS).map(([k,url])=>new Promise(resolve=>{const im=new Image;im.onload=()=>{images[k]=im;resolve()};im.src=url}))).then(()=>{ready=true;draw()});
const ref=()=>DATA.reference.find(r=>r.clock===clock),durations=()=>ref().frames.map(f=>f.duration_ms);
function paths(i){return {approved:ref().frames[i].decoded_path,candidate:active().candidate_frames[i].path,source:sourcePath(i)}}
function sourcePath(i){return DATA.source_display.frames[i].path}
function draw(){if(!ready)return;const p=paths(index);p.source=sourcePath(index);for(const [name,ctx] of Object.entries(ctxs)){ctx.clearRect(0,0,384,512);ctx.drawImage(images[p[name]],0,0,384,512);if(document.getElementById('grid').checked){ctx.strokeStyle='#8aaec044';ctx.lineWidth=1;for(let x=0;x<384;x+=20){ctx.beginPath();ctx.moveTo(x+.5,0);ctx.lineTo(x+.5,512);ctx.stroke()}for(let y=0;y<512;y+=20){ctx.beginPath();ctx.moveTo(0,y+.5);ctx.lineTo(384,y+.5);ctx.stroke()}}}
 const partRows=profile==='matched'?DATA.parts.measurements['candidate'+index]:null;
 document.getElementById('partStatus').textContent='ขนาดรายส่วนยังไม่ผ่าน: ตรวจหัว ไหล่ ลำตัว แขน มือ ขา รองเท้า และจุดต่อ รวม18รายการ / จุดที่ถูกบังยังไม่ทราบ / มุมหน้ากับหลังไม่เทียบความกว้างตรงๆ';
 document.getElementById('partTable').textContent=partRows?Object.entries(partRows).map(([k,v])=>k+': '+(v.status==='MEASURED'?v.value_px.toFixed(1)+'px / '+(100*v.fraction_of_fixed_family_height).toFixed(1)+'% ของ399px / '+v.definition+(v.covers_required_dimension?'':' / partial proxy only'):v.status+' / '+v.reason)).join('\\n'):'ชุดก่อนแก้ขนาดไม่มีจุดวัดรายส่วน ห้ามโอนจุดข้ามสเกล';
 if(document.getElementById('partOverlay').checked&&partRows){for(const [panel,rows] of [['candidate',partRows],['approved',index===0?DATA.parts.measurements.approved0:{}]]){const ctx=ctxs[panel];for(const [k,v] of Object.entries(rows)){if(v.status!=='MEASURED')continue;ctx.strokeStyle='#59ffbb';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(...v.points[0]);ctx.lineTo(...v.points[1]);ctx.stroke();ctx.fillStyle='white';for(const [x,y] of v.points){ctx.beginPath();ctx.arc(x,y,2,0,Math.PI*2);ctx.fill()}}}}
 if(document.getElementById('bones').checked){const ctx=ctxs.source,p=DATA.source.frames[index].points,m=DATA.source_display.matrix,project=q=>[m[0]*q[0]+m[4],m[3]*q[1]+m[5]];for(const [s,c] of [['left','#ff963d'],['right','#369dff']]){ctx.strokeStyle=c;ctx.lineWidth=2;for(const [a,b] of [['hip','knee'],['knee','ankle'],['ankle','toe'],['shoulder','elbow'],['elbow','wrist'],['wrist','palm']]){ctx.beginPath();ctx.moveTo(...project(p[s+'.'+a].xy.rear));ctx.lineTo(...project(p[s+'.'+b].xy.rear));ctx.stroke()}}}
 if(document.getElementById('surfaces').checked){const ctx=ctxs.candidate;for(const [k,t] of Object.entries(active().floor_qa.raster.tracks)){const o=t.observations[index];if(!o.known)continue;const [x0,y0,x1,y1]=o.window;ctx.strokeStyle=k==='near'?'#64d9ff':'#ffad62';ctx.strokeRect(x0,y0,x1-x0,y1-y0);ctx.beginPath();ctx.moveTo(o.xy[0]-4,o.xy[1]);ctx.lineTo(o.xy[0]+4,o.xy[1]);ctx.moveTo(o.xy[0],o.xy[1]-4);ctx.lineTo(o.xy[0],o.xy[1]+4);ctx.stroke()}}
 for(const [name,o] of Object.entries(obs()[index]))if(o.xy){const ctx=ctxs.candidate;ctx.fillStyle='#5dffae';ctx.beginPath();ctx.arc(...o.xy,3,0,Math.PI*2);ctx.fill();ctx.fillText(name,o.xy[0]+5,o.xy[1]-5)}
 const sq=profile==='matched'?DATA.size_qa:DATA.before_size_qa,first=sq.neutral_comparison[0],last=sq.neutral_comparison[1],ft=active().floor_qa.raster.tracks;document.getElementById('verdict').textContent='ยังไม่ผ่าน: GIF เก่าท่ายืน399px / ใหม่เฟรมแรก'+first.observed_height_px+'px / กลับมายืนอย่างน้อย'+last.observed_height_px+'px (ต้นทางถูกตัด) — เท้าใกล้'+ft.near.range_display_px[0]+'px / ไกล'+ft.far.range_display_px[0]+'px เกิน6px; สัดส่วนหัวกับตัวยังไม่ยืนยัน';document.getElementById('frame').value=index;document.getElementById('status').textContent='เฟรม '+(index+1)+' / approved '+durations()[index]+'ms / source '+DATA.source.frames[index].time_seconds.toFixed(3)+'s / ภาพใหม่ยังไม่ผ่าน';document.getElementById('notes').textContent=JSON.stringify(obs()[index],null,2);
}
function select(i){running=false;index=Math.max(0,Math.min(7,i));draw()}
function annotate(xy){obs()[index][document.getElementById('landmark').value]={xy,visibility:xy?'visible':'unknown',image_sha256:active().candidate_frames[index].sha256};draw()}
document.getElementById('candidate').onclick=e=>{const b=e.target.getBoundingClientRect();annotate(document.getElementById('visibility').value==='visible'?[Math.round((e.clientX-b.left)*384/b.width*10)/10,Math.round((e.clientY-b.top)*512/b.height*10)/10]:null)};
document.getElementById('profile').onchange=e=>{profile=e.target.value;running=false;draw()};document.getElementById('unknown').onclick=()=>annotate(null);document.getElementById('frame').oninput=e=>select(+e.target.value);document.getElementById('clock').onchange=e=>{clock=e.target.value;select(0)};for(const k of ['grid','bones','surfaces','partOverlay'])document.getElementById(k).onchange=draw;
document.onkeydown=e=>{if(['INPUT','SELECT'].includes(e.target.tagName))return;if(e.key==='ArrowRight')select(index+1);if(e.key==='ArrowLeft')select(index-1)};
function atTime(t){let n=0,sum=0;const ds=durations();while(n<7&&sum+ds[n]<=t){sum+=ds[n];n++}return n}
function tick(t){if(!running)return;index=atTime(t-start);draw();if(t-start>=durations().reduce((a,b)=>a+b,0)){running=false;return}requestAnimationFrame(tick)}document.getElementById('play').onclick=()=>{index=0;start=performance.now();running=true;requestAnimationFrame(tick)};
function exportData(){return {scope:'Manual visible-image observations; unknown occlusion is not inferred. No automatic art approval.',candidate_frames:active().candidate_frames,approved_gif:{path:ref().approved_gif_path,sha256:ref().approved_gif_sha256},profile,observations:obs()}}
document.getElementById('download').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(exportData(),null,2)],{type:'application/json'}));a.download='visible-image-observations.json';a.click();URL.revokeObjectURL(a.href)};
window.review={get ready(){return ready},get index(){return index},get running(){return running},get clock(){return clock},get profile(){return profile},get data(){return active()},allData:DATA,select,atTime,exportData,clearAnnotations(){for(const rows of Object.values(observations))for(const o of rows)for(const k of Object.keys(o))delete o[k];draw()},frame(i,name='candidate'){select(i);return ctxs[name].canvas.toDataURL('image/png')}};
</script>'''
(P/'approved-gif-review.html').write_text(html.replace('__DATA__',json.dumps(d,separators=(',',':'))).replace('__IMAGES__',json.dumps(images,separators=(',',':'))))
print('Offline approved GIF reviewer built')
